-- Panasonic 50クラス 加湿フィルター（FE-ZGV08）を追加してリンク
with p as (
  insert into parts (name, category, kind, manufacturer, manufacturer_part_number, image_url)
  values ('加湿フィルター FE-ZGV08', 'filter', 'oem', 'Panasonic', 'FE-ZGV08',
          'https://thumbnail.image.rakuten.co.jp/@0_mall/yamada-denki/cabinet/a07000037/5105411010.jpg?_ex=128x128') returning id
)
insert into appliance_parts (appliance_id, part_id)
select a.id, p.id from appliances a cross join p
where a.manufacturer = 'Panasonic' and a.category = 'air_purifier' and a.model_number in ('F-VXG50','F-VXH50')
on conflict do nothing;
